  const bus = new InMemoryEventBus()

  registerOrderDeliveredSubscriber(bus, { commands: { CreateInvoice } } as any)

  await bus.publish('order.delivered', {
    orderId: 'ord_789',
    customerId: 'cus_456',
    deliveredAt: '2026-06-08T12:00:00.000Z'
  })

  expect(CreateInvoice.execute).toHaveBeenCalledWith(expect.objectContaining({
    orderId: 'ord_789',
    idempotencyKey: 'order:ord_789:invoice'
  }))
})
```

